void steam_gen_64::thread_ap_NS_fsm() {
    switch (ap_CS_fsm.read().to_uint64()) {
        case 1 : 
            if ((esl_seteq<1,1,1>(ap_const_logic_1, ap_CS_fsm_state1.read()) && esl_seteq<1,1,1>(ap_start.read(), ap_const_logic_1))) {
                ap_NS_fsm = ap_ST_fsm_state2;
            } else {
                ap_NS_fsm = ap_ST_fsm_state1;
            }
            break;
        case 2 : 
            if ((esl_seteq<1,1,1>(ap_const_logic_1, ap_CS_fsm_state2.read()) && !(esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_data_V_1_ack_in.read()) || esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_keep_V_1_ack_in.read()) || esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_strb_V_1_ack_in.read()) || esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_user_V_1_ack_in.read()) || esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_last_V_1_ack_in.read()) || esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_id_V_1_ack_in.read()) || esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_dest_V_1_ack_in.read()) || esl_seteq<1,1,1>(ap_const_boolean_1, ap_block_state2_io.read())) && esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_data_V_1_state.read()[0]) && esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_keep_V_1_state.read()[0]) && esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_strb_V_1_state.read()[0]) && esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_user_V_1_state.read()[0]) && esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_last_V_1_state.read()[0]) && esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_id_V_1_state.read()[0]) && esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_dest_V_1_state.read()[0]) && esl_seteq<1,1,1>(ap_const_lv1_0, tmp_1_fu_109_p2.read()))) {
                ap_NS_fsm = ap_ST_fsm_state1;
            } else if ((esl_seteq<1,1,1>(ap_const_logic_1, ap_CS_fsm_state2.read()) && esl_seteq<1,1,1>(ap_const_lv1_1, tmp_1_fu_109_p2.read()) && !(esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_data_V_1_ack_in.read()) || esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_keep_V_1_ack_in.read()) || esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_strb_V_1_ack_in.read()) || esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_user_V_1_ack_in.read()) || esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_last_V_1_ack_in.read()) || esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_id_V_1_ack_in.read()) || esl_seteq<1,1,1>(ap_const_logic_0, stream_data_gen_V_dest_V_1_ack_in.read()) || esl_seteq<1,1,1>(ap_const_boolean_1, ap_block_state2_io.read())))) {
                ap_NS_fsm = ap_ST_fsm_state3;
            } else {
                ap_NS_fsm = ap_ST_fsm_state2;
            }
            break;
        case 4 : 
            if ((esl_seteq<1,1,1>(ap_const_logic_1, ap_CS_fsm_state3.read()) && esl_seteq<1,1,1>(stream_data_gen_V_data_V_1_ack_in.read(), ap_const_logic_1))) {
                ap_NS_fsm = ap_ST_fsm_state2;
            } else {
                ap_NS_fsm = ap_ST_fsm_state3;
            }
            break;
        default : 
            ap_NS_fsm = "XXX";
            break;
    }
}

void steam_gen_64::thread_hdltv_gen() {
    const char* dump_tv = std::getenv("AP_WRITE_TV");
    if (!(dump_tv && string(dump_tv) == "on")) return;

    wait();

    mHdltvinHandle << "[ " << endl;
    mHdltvoutHandle << "[ " << endl;
    int ap_cycleNo = 0;
    while (1) {
        wait();
        const char* mComma = ap_cycleNo == 0 ? " " : ", " ;
        mHdltvinHandle << mComma << "{"  <<  " \"ap_rst_n\" :  \"" << ap_rst_n.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"ap_start\" :  \"" << ap_start.read() << "\" ";
        mHdltvoutHandle << mComma << "{"  <<  " \"ap_done\" :  \"" << ap_done.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"ap_idle\" :  \"" << ap_idle.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"ap_ready\" :  \"" << ap_ready.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"stream_data_gen_TDATA\" :  \"" << stream_data_gen_TDATA.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"stream_data_gen_TVALID\" :  \"" << stream_data_gen_TVALID.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"stream_data_gen_TREADY\" :  \"" << stream_data_gen_TREADY.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"stream_data_gen_TKEEP\" :  \"" << stream_data_gen_TKEEP.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"stream_data_gen_TSTRB\" :  \"" << stream_data_gen_TSTRB.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"stream_data_gen_TUSER\" :  \"" << stream_data_gen_TUSER.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"stream_data_gen_TLAST\" :  \"" << stream_data_gen_TLAST.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"stream_data_gen_TID\" :  \"" << stream_data_gen_TID.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"stream_data_gen_TDEST\" :  \"" << stream_data_gen_TDEST.read() << "\" ";
        mHdltvinHandle << " , " <<  " \"LEN\" :  \"" << LEN.read() << "\" ";
        mHdltvinHandle << "}" << std::endl;
        mHdltvoutHandle << "}" << std::endl;
        ap_cycleNo++;
    }
}

